      ld=ledger_date[id]; bd=bank_date[id]
      eq_a=(la==ba); eq_d=(ld==bd)
      if (eq_a && eq_d) matched++
      if (!eq_a) { am_ids[am_n++]=id }
      if (!eq_d) { dm_ids[dm_n++]=id }
    } else {
      mib_ids[mib_n++]=id
    }
  }
  for (i=0; i<bank_n; i++) {
    id=bank_ids[i]
    if (!(id in ledger_date)) { mil_ids[mil_n++]=id }
  }
  # sort detail arrays ascending (lexicographic)
  # simple bubble? use asort
  # asort sorts values and returns count; need to handle empty
  if (am_n>0) asort(am_ids, am_sorted); else split("", am_sorted)
  if (dm_n>0) asort(dm_ids, dm_sorted); else split("", dm_sorted)
  if (mib_n>0) asort(mib_ids, mib_sorted); else split("", mib_sorted)
  if (mil_n>0) asort(mil_ids, mil_sorted); else split("", mil_sorted)

  out=out_file
  print "ledger_rows: " ledger_n > out
  print "bank_rows: " bank_n >> out
  # dup may be unset if no dups? init 0
  print "duplicate_bank_rows: " (dup+0) >> out
  print "ledger_total: " fmt_cents(ledger_sum+0) >> out
  print "bank_total: " fmt_cents(bank_sum+0) >> out
  print "matched: " matched >> out
  print "amount_mismatch: " am_n >> out
  for (i=1; i<=am_n; i++) {
    id=am_sorted[i]
    print "  " id " ledger=" fmt_cents(ledger_cents[id]) " bank=" fmt_cents(bank_cents[id]) >> out
  }
  print "date_mismatch: " dm_n >> out
  for (i=1; i<=dm_n; i++) {
    id=dm_sorted[i]
    print "  " id " ledger=" ledger_date[id] " bank=" bank_date[id] >> out
  }
  print "missing_in_bank: " mib_n >> out
  for (i=1; i<=mib_n; i++) {
    id=mib_sorted[i]
    print "  " id >> out
  }
  print "missing_in_ledger: " mil_n >> out
  for (i=1; i<=mil_n; i++) {
    id=mil_sorted[i]
    print "  " id >> out
  }
}

